#include "lane_scene.h"
#include <string.h>
int lane_scene_build(const lane_game_state *s,uint32_t dst,lane_scene *o){if(!s||!o||!dst)return GPU_DRIVER_ARGUMENT;lane_scene t;memset(&t,0,sizeof t);for(unsigned r=0;r<LANE_ROWS;r++){if(t.count>=LANE_SCENE_MAX_COMMANDS)return GPU_DRIVER_FULL;t.commands[t.count++]=(gpu_command){.op=GPU_OP_FILL,.dst_addr=dst+((uint32_t)r*96u+24u)*1920u,.dst_stride=1920,.width_pixels=864,.height_pixels=96,.color=0x07e0};}for(unsigned i=0;i<LANE_MAX_PLANTS;i++)if(s->plants[i].active){if(t.count>=LANE_SCENE_MAX_COMMANDS)return GPU_DRIVER_FULL;lane_plant p=s->plants[i];t.commands[t.count++]=(gpu_command){.op=GPU_OP_FILL,.dst_addr=dst+((uint32_t)p.row*96u+16u)*1920u+(uint32_t)p.col*96u*2u,.dst_stride=1920,.width_pixels=48,.height_pixels=48,.color=0x07e0};}for(unsigned i=0;i<LANE_MAX_ENEMIES;i++)if(s->enemies[i].active){if(t.count>=LANE_SCENE_MAX_COMMANDS)return GPU_DRIVER_FULL;lane_enemy e=s->enemies[i];uint16_t x=(uint16_t)(e.x16>>16);t.commands[t.count++]=(gpu_command){.op=GPU_OP_FILL,.dst_addr=dst+((uint32_t)e.row*96u+32u)*1920u+x*2u,.dst_stride=1920,.width_pixels=32,.height_pixels=32,.color=0xf800};}t.crc=0;for(unsigned i=0;i<t.count;i++)t.crc=(t.crc*16777619u)^t.commands[i].dst_addr;*o=t;return 0;}
